import json
from pathlib import Path
worlds=[
(1,'Blunder Hills','Dein Fundament','Mining · Chopping · Smithing','Amarok','Lege einen Kampf- und einen Sammel-Schwerpunkt fest. Ein neues Item ist nur dann ein Fortschritt, wenn du es auch sinnvoll einsetzen kannst.',['Prüfe vor einer neuen Karte Trefferchance und Überleben in der AFK-Info.','Richte die Produktion am Anvil ein und behalte die Kapazität im Blick.','Vergleiche fehlende Materialien über die Rezept-Verknüpfungen in der Datenbank.','Arbeite dich zu Amarok vor und pflege parallel deine accountweiten Systeme.']),
(2,'Yum Yum Desert','Accountweite Stärke','Alchemy · Fishing · Catching','Efaunt','Mit Alchemy wächst nicht nur ein Charakter. Vergleiche Bubble-Effekte und ihre Materialkosten, bevor du deinen gesamten Vorrat ausgibst.',['Starte Alchemy und prüfe neue Bubbles und Vials.','Nutze Fishing und Catching gezielt für tatsächlich benötigte Materialien.','Prüfe Post Office und Obols als zusätzliche Verbesserungen.','Bereite den nächsten Weltboss mit aktueller Ausrüstung und Nahrung vor.']),
(3,'Frostbite Tundra','Produktion aufbauen','Construction · Trapping · Worship','Chizoar','Mehr Systeme bedeuten mehr Abhängigkeiten. Der Atlas zeigt Zutaten, Fundorte und Verwendungszwecke nebeneinander, damit du Engpässe erkennst.',['Richte Construction ein und prüfe verfügbare Gebäude.','Nimm 3D-Printer-Samples nach relevanten Verbesserungen neu auf.','Vergleiche Verbrauch und Produktion deiner Refinery, bevor du Ränge erhöhst.','Pflege Trapping und Worship auf deinen Charakteren.']),
(4,'Hyperion Nebula','Boni verbinden','Cooking · Breeding · Laboratory','Troll','Breeding, Gewürze und Cooking hängen zusammen. Verfolge diese Kette über die Detailseiten und plane Labor-Belegung bewusst.',['Beginne Breeding und suche nach dem nächsten erreichbaren Gewürz.','Vergleiche Mahlzeiten nach ihrem Nutzen für dein aktuelles Ziel.','Prüfe aktivierte Laboratory-Verbindungen nach jeder Umstellung.','Behalte Rift und Tome als weitere Fortschrittsbereiche im Blick.']),
(5,'Smolderin’ Plateau','Langfristig wachsen','Sailing · Divinity · Gaming','Kattlekruk','Sailing-Artefakte, Götter und Gaming-Boni greifen in viele ältere Systeme ein. Nutze die Datenbank, um Auswirkungen nachzuschlagen.',['Starte Sailing und kontrolliere Inseln sowie Artefakte.','Prüfe Divinity-Stile und Verbindungen, bevor du Charaktere umverteilst.','Entwickle Gaming und seine Upgrades passend zu deinem Fortschritt.','Erkunde die verfügbaren Caverns im Hole und ihre Voraussetzungen.']),
(6,'Spirited Valley','Drei neue Baustellen','Farming · Sneaking · Summoning','Emperor','Farming, Sneaking und Summoning erweitern deinen Account. Arbeite an erreichbaren Verbesserungen, statt Ressourcen allein auf teure Einzelupgrades zu konzentrieren.',['Schalte die neuen Systeme frei und starte ihre Produktion.','Vergleiche Farming-Markt, Exotic Market und Land Ranks.','Prüfe Ausrüstung und Chancen beim Sneaking.','Verknüpfe Summoning-Kämpfe mit ihren Belohnungen und Upgrades.']),
(7,'Shimmerfin Deep','Das tiefe Endgame','Research · Spelunking · weitere Systeme',None,'Der importierte Datenstand enthält unter anderem Research, Spelunking, Minehead, Sushi Station, Jelly Operator und Menagerie. Die Detailwerte sind ein Community-Snapshot.',['Prüfe Research-Squares und Observations im Katalog.','Vergleiche Spelunking-Tunnel und Shop-Upgrades.','Schlage Legend Talents, Zenith und Clam Work nach.','Kontrolliere neue Inhalte zusätzlich anhand aktueller Spiel- und Patchangaben.'])]
guides=[]
for w,name,title,skills,boss,intro,steps in worlds:
 guides.append({'id':f'world-{w}','world':w,'title':f'Welt {w}: {title}','subtitle':skills,'intro':intro,'steps':steps,'icon':f'/data/UImap{w}.png','type':'Orientierung','sources':['toolbox','reddit'],'status':'Redaktionelle Orientierung; keine getestete Speedrun-Route','boss':boss})
extras=[
('alchemy',2,'Alchemy ohne Blindflug','Bubbles, Vials und Sigils','bubble:aUpgradesO0',['Suche den gewünschten Bonus in der Enzyklopädie und öffne die passende Bubble.','Vergleiche Material- und Flüssigkeitskosten. Die angezeigten Formeln sind Basisdaten; Account-Rabatte sind nicht eingerechnet.','Unterscheide einen neuen Bonus von einem höheren Level eines bestehenden Bonus.','Speichere dein nächstes Upgrade in der Merkliste.']),
('crafting',1,'Vom Wunschitem zum Rezept','Materialien und Herkunft verknüpfen','item:Copper',['Öffne ein Item und schaue unter „Hergestellt aus“ nach.','Wechsle zur Zutat, um ihre Dropquellen oder weitere Rezepte zu sehen.','Nutze die Rezeptmenge für mehrere Exemplare.','Der Rechner zeigt Basisrezepte; individuelle Rabatte und vorhandene Lagerbestände werden nicht verrechnet.']),
('drops',1,'Wo droppt mein Item?','Monster, Karten und Belohnungen','monster:mushG',['Suche nach dem englischen Ingame-Namen des Items.','Öffne „Wird fallen gelassen von“ und wechsle zum Monster.','Prüfe dessen Kartenverknüpfungen sowie die Basis-Dropchance.','Die Dropchance ist kein persönlicher Loot-Versprecher: individuelle Boni, Sonderregeln und Drop-Tabellen können die tatsächliche Chance verändern.']),
('classes',1,'Deinen Klassenweg verstehen','Talente und Klassenwechsel','class:Beginner',['Öffne die Kategorie Klassen.','Folge den Verknüpfungen für Klassenwechsel und Talente.','Vergleiche Talentbeschreibungen für Kampf und Sammeln getrennt.','Feste Skillpunkt-Verteilungen hängen von deinem Level, Ziel und Account ab; der Atlas erfindet dafür keinen universellen Build.']),
('construction',3,'Construction & Refinery planen','Gebäude, Materialien und Produktion','building:0',['Sieh dir alle Gebäude in der Enzyklopädie an.','Prüfe die Materialien für dein nächstes Ziel.','Vergleiche Refinery-Ressourcen mit deiner verfügbaren Produktion.','Plane eine Produktionsreserve, bevor du dauerhaft mehr Material verbrauchst.']),
('cooking',4,'Cooking & Breeding verbinden','Von Gewürzen zu Mahlzeiten','meal:0',['Vergleiche die Boni der Mahlzeiten.','Öffne verknüpfte Gewürze und ihre Herkunft.','Prüfe Breeding-Gene und Upgrades getrennt von Mahlzeit-Leveln.','Konzentriere deine nächsten Schritte auf einen konkret benötigten Accountbonus.']),
('sailing',5,'Artefakte gezielt nachschlagen','Inseln und langfristige Boni','artifact:0',['Filtere die Datenbank auf Artefakte.','Lies den Effekt und die verknüpften Inseln.','Unterscheide Basisdaten von accountabhängigen Chancen.','Markiere interessante Artefakte für deinen nächsten Spielbesuch.']),
('endgame',7,'Neue Systeme im Blick behalten','Welt 7 & Masterklassen','world:7',['Öffne die Welt-7-Übersicht und filtere nach einem System.','Prüfe Royal Armory, Grimoire, Compass und Tesseract über die Kategorien.','Lies bei numerischen Effekten auch die Rohformeln.','Vergleiche den importierten Commit-Stand mit aktuellen Patchnotes.']),
('routine',1,'Eine Routine, die zu dir passt','Ziele statt endloser Aufgaben','world:1',['Wähle deine aktuelle Welt unter „Mein Abenteuer“.','Hake nur Aufgaben ab, die für deinen Account bereits zugänglich sind.','Speichere konkrete Items und Upgrades in der Merkliste.','Exportiere deinen Fortschritt gelegentlich als Backup. Checklisten werden absichtlich nicht automatisch zurückgesetzt.'])]
